import json,pathlib,csv,hashlib,zipfile
import pretty_midi,numpy as np
root=pathlib.Path(__file__).resolve().parents[1]/'docs/research-runs/2026-10-29-current-musicality';x=json.loads((root/'transcription-manifest.json').read_text());rows=[]
for r in x['results']:
 p=root/'transcriptions'/(r['id']+'-inferred.mid');m=pretty_midi.PrettyMIDI(str(p));notes=[n for i in m.instruments for n in i.notes];assert len(notes)==r['noteCount'];assert all(0<=n.pitch<=127 and 0<=n.start<n.end<=r['durationSeconds']+.15 for n in notes);assert all(np.isfinite([n.start,n.end,n.velocity]).all() for n in notes)
 rows.append({'id':r['id'],'category':r['category'],'conceptId':r.get('conceptId'),'notes':len(notes),'pitchLow':r['pitchRange'][0],'pitchHigh':r['pitchRange'][1],'uncalibratedActivation':r['uncalibratedMeanActivation'],'inferredSemitoneOverlap':r['inferredSemitoneOverlapFraction'],'aggregateChromaAgreement':r['audioVsMidiChromaCosine'],'unknownChordFraction':sum(c['quality']=='unknown' for c in r['coarseAudioChordCandidates'])/len(r['coarseAudioChordCandidates']),'sourceKeyConfidence':r.get('sourceKeyConfidence'),'midiSha256':hashlib.sha256(p.read_bytes()).hexdigest()})
